// Unifica los tres canales al mismo formato.
// WhatsApp y Telegram traen su propia forma; el formulario llega en $json.body.
const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  let canal = 'desconocido';
  let remitente = '';
  let ref_respuesta = '';
  let texto = '';

  if (j.body && (j.body.mensaje !== undefined || j.body.email !== undefined)) {
    // Formulario web via webhook: los campos viven en $json.body
    canal = 'formulario';
    remitente = j.body.email || '';
    ref_respuesta = j.body.email || '';
    texto = j.body.mensaje || '';
  } else if (j.message && j.message.chat) {
    // Telegram
    canal = 'telegram';
    remitente = j.message.from ? (j.message.from.username || String(j.message.from.id)) : '';
    ref_respuesta = String(j.message.chat.id);
    texto = j.message.text || '';
  } else if (j.messages || (j.entry && j.entry.length)) {
    // WhatsApp Cloud API
    const cambio = j.entry ? j.entry[0]?.changes?.[0]?.value : j;
    const msg = (cambio?.messages || j.messages || [])[0] || {};
    canal = 'whatsapp';
    remitente = msg.from || '';
    ref_respuesta = msg.from || '';
    texto = msg.text?.body || '';
    if (!texto && msg.type && msg.type !== 'text') {
      texto = '[MENSAJE SIN TEXTO: ' + msg.type + '. Escalar a persona]';
    }
  }

  salida.push({
    json: {
      id: $execution.id + '-' + $itemIndex,
      fecha: new Date().toISOString(),
      canal,
      remitente,
      ref_respuesta,
      texto: String(texto).slice(0, 4000),
      estado: 'nuevo',
    },
  });
}
return salida;

// Parsea la respuesta del modelo sin fiarse de que venga limpia.
const salida = [];
for (const item of $input.all()) {
  const mensaje = $('Filtrar vacíos y spam').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    // Si el modelo falla, mejor escalar a persona que perder el mensaje.
    datos = { tipo: 'otros', prioridad: 'alta', escalar: true, motivo: 'triaje no parseable: ' + bruto.slice(0, 150), borrador: '' };
  }
  salida.push({
    json: {
      ...mensaje,
      tipo: datos.tipo ?? 'otros',
      prioridad: datos.prioridad ?? 'alta',
      escalar: Boolean(datos.escalar),
      motivo: datos.motivo ?? '',
      borrador: datos.borrador ?? '',
      estado: datos.escalar ? 'escalado' : 'pendiente_aprobacion',
    },
  });
}
return salida;

